#!/bin/sh

set -xe

./собрать.sh
mkdir -p ./сборка/примеры/
mkdir -p ./сборка/тесты/

test_fasm() {
    ./сборка/цуяк комп -вывод ./сборка/примеры/01-привет     ./примеры/01-привет.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/02-цикл       ./примеры/02-цикл.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/03-имя        ./примеры/03-имя.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/04-физз-базз  ./примеры/04-физз-базз.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/05-фибоначчи  ./примеры/05-фибоначчи.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/06-рейлиб     ./примеры/06-рейлиб.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/07-рекурсия   ./примеры/07-рекурсия.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/08-структуры  ./примеры/08-структуры.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/09-правило110 ./примеры/09-правило110.цуя
    ./сборка/цуяк комп -вывод ./сборка/примеры/10-игра-жизнь ./примеры/10-игра-жизнь.цуя
    ./сборка/цуяк комп -вывод ./сборка/тесты/тест            ./тесты/тест.цуя

    ./сборка/примеры/01-привет               > ./сборка/примеры/01-привет.цуя.вывод.фазм     && diff -u ./примеры/01-привет.цуя.вывод     ./сборка/примеры/01-привет.цуя.вывод.фазм
    ./сборка/примеры/02-цикл                 > ./сборка/примеры/02-цикл.цуя.вывод.фазм       && diff -u ./примеры/02-цикл.цуя.вывод       ./сборка/примеры/02-цикл.цуя.вывод.фазм
    echo 'Алексей' | ./сборка/примеры/03-имя > ./сборка/примеры/03-имя.цуя.вывод.фазм        && diff -u ./примеры/03-имя.цуя.вывод        ./сборка/примеры/03-имя.цуя.вывод.фазм
    ./сборка/примеры/04-физз-базз            > ./сборка/примеры/04-физз-базз.цуя.вывод.фазм  && diff -u ./примеры/04-физз-базз.цуя.вывод  ./сборка/примеры/04-физз-базз.цуя.вывод.фазм
    ./сборка/примеры/05-фибоначчи            > ./сборка/примеры/05-фибоначчи.цуя.вывод.фазм  && diff -u ./примеры/05-фибоначчи.цуя.вывод  ./сборка/примеры/05-фибоначчи.цуя.вывод.фазм
    #./сборка/примеры/06-рейлиб              > ./сборка/примеры/06-рейлиб.цуя.вывод.фазм     && diff -u ./примеры/06-рейлиб.цуя.вывод     ./сборка/примеры/06-рейлиб.цуя.вывод.фазм
    ./сборка/примеры/07-рекурсия             > ./сборка/примеры/07-рекурсия.цуя.вывод.фазм   && diff -u ./примеры/07-рекурсия.цуя.вывод   ./сборка/примеры/07-рекурсия.цуя.вывод.фазм
    ./сборка/примеры/08-структуры            > ./сборка/примеры/08-структуры.цуя.вывод.фазм  && diff -u ./примеры/08-структуры.цуя.вывод  ./сборка/примеры/08-структуры.цуя.вывод.фазм
    ./сборка/примеры/09-правило110           > ./сборка/примеры/09-правило110.цуя.вывод.фазм && diff -u ./примеры/09-правило110.цуя.вывод ./сборка/примеры/09-правило110.цуя.вывод.фазм
    ./сборка/примеры/10-игра-жизнь           > ./сборка/примеры/10-игра-жизнь.цуя.вывод.фазм && diff -u ./примеры/10-игра-жизнь.цуя.вывод ./сборка/примеры/10-игра-жизнь.цуя.вывод.фазм
    ./сборка/тесты/тест                      > ./сборка/тесты/тест.цуя.вывод.фазм            && diff -u ./тесты/тест.цуя.вывод            ./сборка/тесты/тест.цуя.вывод.фазм
}

test_inter() {
    ./сборка/цуяк интер ./примеры/01-привет.цуя               > ./сборка/примеры/01-привет.цуя.вывод.интер     && diff -u ./примеры/01-привет.цуя.вывод     ./сборка/примеры/01-привет.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/02-цикл.цуя                 > ./сборка/примеры/02-цикл.цуя.вывод.интер       && diff -u ./примеры/02-цикл.цуя.вывод       ./сборка/примеры/02-цикл.цуя.вывод.интер
    echo 'Алексей' | ./сборка/цуяк интер ./примеры/03-имя.цуя > ./сборка/примеры/03-имя.цуя.вывод.интер        && diff -u ./примеры/03-имя.цуя.вывод        ./сборка/примеры/03-имя.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/04-физз-базз.цуя            > ./сборка/примеры/04-физз-базз.цуя.вывод.интер  && diff -u ./примеры/04-физз-базз.цуя.вывод  ./сборка/примеры/04-физз-базз.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/05-фибоначчи.цуя            > ./сборка/примеры/05-фибоначчи.цуя.вывод.интер  && diff -u ./примеры/05-фибоначчи.цуя.вывод  ./сборка/примеры/05-фибоначчи.цуя.вывод.интер
    #./сборка/цуяк интер ./примеры/06-рейлиб.цуя              > ./сборка/примеры/06-рейлиб.цуя.вывод.интер     && diff -u ./примеры/06-рейлиб.цуя.вывод     ./сборка/примеры/06-рейлиб.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/07-рекурсия.цуя             > ./сборка/примеры/07-рекурсия.цуя.вывод.интер   && diff -u ./примеры/07-рекурсия.цуя.вывод   ./сборка/примеры/07-рекурсия.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/08-структуры.цуя            > ./сборка/примеры/08-структуры.цуя.вывод.интер  && diff -u ./примеры/08-структуры.цуя.вывод  ./сборка/примеры/08-структуры.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/09-правило110.цуя           > ./сборка/примеры/09-правило110.цуя.вывод.интер && diff -u ./примеры/09-правило110.цуя.вывод ./сборка/примеры/09-правило110.цуя.вывод.интер
    ./сборка/цуяк интер ./примеры/10-игра-жизнь.цуя           > ./сборка/примеры/10-игра-жизнь.цуя.вывод.интер && diff -u ./примеры/10-игра-жизнь.цуя.вывод ./сборка/примеры/10-игра-жизнь.цуя.вывод.интер
    ./сборка/цуяк интер ./тесты/тест.цуя                      > ./сборка/тесты/тест.цуя.вывод.интер            && diff -u ./тесты/тест.цуя.вывод            ./сборка/тесты/тест.цуя.вывод.интер
}

test_fasm
test_inter
